package com.autoops.ai.controller;import com.autoops.ai.service.AIToolExecutor;import com.autoops.common.security.CurrentUser;import org.springframework.web.bind.annotation.*;import java.util.Map;@RestController @RequestMapping("/api/ai/tools")public class AIToolController{private final AIToolExecutor tools;private final CurrentUser current;public AIToolController(AIToolExecutor t,CurrentUser c){tools=t;current=c;}public record Call(String name,Map<String,Object> arguments){}@PostMapping public Object call(@RequestBody Call c){return tools.execute(c.name(),c.arguments()==null?Map.of():c.arguments(),current.id());}}
